const $=id=>document.getElementById(id);
export function createArrivalUI(room,api){
 const element=document.createElement('section');element.id='arrivalUI';element.className='hidden';element.setAttribute('aria-label','Welcome to the city tutorial');
 element.innerHTML='<header class="arrival-header"><a href="/" class="arrival-brand">GETAWAY</a><span>CHAPTER 01 / A PLACE TO CALL HOME</span><button id="arrivalLeave" class="small-btn hidden">END REPLAY</button></header><div class="arrival-objective"><b id="arrivalStep">01 / MEET YOUR NEIGHBOR</b><span id="arrivalGoal">Your story starts here.</span></div><article class="arrival-dialog"><div class="arrival-portrait"><img src="/assets/models/passengers/character-k.png" alt="Jules, your blocky neighbor"><span>JULES<br><small>YOUR NEIGHBOR</small></span></div><div class="arrival-speech"><span class="arrival-eyebrow">A NEW CITY. YOUR NEXT CHAPTER.</span><h1 id="arrivalTitle">WELCOME TO THE CITY.</h1><p id="arrivalCopy">I’m Jules, your new neighbor. See the green awning? That’s your apartment. Come on — let’s get you settled.</p><p id="arrivalError" role="alert" hidden></p><button id="arrivalNext" class="primary">LET’S GO →</button><small id="arrivalHint">E / ENTER TO CONTINUE</small></div></article><div class="arrival-controls" aria-label="Walk controls"><button data-arrival-walk="up" aria-label="Walk forward">↑</button><button data-arrival-walk="left" aria-label="Walk left">←</button><button data-arrival-walk="down" aria-label="Walk backward">↓</button><button data-arrival-walk="right" aria-label="Walk right">→</button></div>';
 $('ui').appendChild(element);let phase='welcome',busy=false,replay=false,last='';
 function refresh(){const near=room.nearDoor,key=[phase,near,busy,room.navigating].join('|');$('arrivalGoal').textContent=phase==='welcome'?'Your story starts here.':near?'You made it. Open your front door.':Math.ceil(room.distance)+' m · FOLLOW THE GOLD MARKERS';if(key===last)return;last=key;element.dataset.phase=phase;
  $('arrivalStep').textContent=phase==='welcome'?'01 / MEET YOUR NEIGHBOR':'02 / WALK TO YOUR APARTMENT';
  $('arrivalTitle').textContent=phase==='welcome'?'WELCOME TO THE CITY.':near?'HERE’S YOUR NEW PLACE.':'LET’S WALK HOME.';
  $('arrivalCopy').textContent=phase==='welcome'?'I’m Jules, your new neighbor. See the green awning? That’s your apartment. Come on — let’s get you settled.':near?'Your keys are ready. Open the door, make yourself at home, then we’ll find you a ride.':'Follow me to the green awning. Use WASD or the arrows to walk. You can also click the pavement, or use the walk button below.';
  $('arrivalNext').textContent=busy?'GETTING YOUR KEYS…':phase==='welcome'?'LET’S GO →':near?'E · OPEN YOUR FRONT DOOR':room.navigating?'WALKING TO YOUR APARTMENT…':'WALK TO THE FRONT DOOR →';
  $('arrivalNext').disabled=busy;$('arrivalHint').textContent=phase==='welcome'?'E / ENTER TO CONTINUE':near?'E / ENTER TO GO INSIDE':'WASD / ARROWS · CLICK OR TAP TO WALK';
 }
 function show(isReplay=false){replay=isReplay;phase='welcome';busy=false;last='';room.reset();$('arrivalError').hidden=true;$('arrivalLeave').classList.toggle('hidden',!replay);element.classList.remove('hidden');refresh();$('arrivalNext').focus({preventScroll:true});}
 async function next(){if(busy)return;if(phase==='welcome'){phase='walk';room.begin();api.clear();refresh();return;}if(!room.nearDoor){room.walkTo();refresh();return;}busy=true;$('arrivalError').hidden=true;refresh();try{await api.complete(replay);room.openDoor();phase='enter';await new Promise(r=>setTimeout(r,650));hide();api.enter(replay);}catch(error){$('arrivalError').textContent='Your keys could not be saved. '+error.message+' Try the door again.';$('arrivalError').hidden=false;}finally{busy=false;refresh();}}
 function hide(){element.classList.add('hidden');api.clear();}
 $('arrivalNext').onclick=()=>void next();$('arrivalLeave').onclick=()=>{if(!busy){hide();api.enter(true);}};
 for(const button of element.querySelectorAll('[data-arrival-walk]')){const key=button.dataset.arrivalWalk;button.addEventListener('pointerdown',e=>{if(phase==='welcome'||busy)return;e.preventDefault();button.setPointerCapture(e.pointerId);api.move(key,true);});for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,()=>api.move(key,false));}
 return{show,hide,next,update:refresh,get walking(){return phase==='walk'&&!busy;},get busy(){return busy;}};
}
